using ChartScene.Charting;
using ChartScene.Core;
using ChartScene.Data;

public static partial class AdditionalTests
{
    static partial void RegisterCharting(TestSuite suite)
    {
        suite.Run("numeric coordinate inverse",()=> { var a=new NumericAxis {VisibleRange=new(-100,300)}; var c=new CoordinateCalculator(a,40,800); for(int i=0;i<=100;i++) { double x=-100+i*4; TestSuite.Near(c.GetDataValue(c.GetCoordinate(x)),x); } });
        suite.Run("vertical and flipped coordinates",()=> { var a=new NumericAxis {AxisAlignment=AxisAlignment.Left,VisibleRange=new(0,100)}; TestSuite.Near(new CoordinateCalculator(a,10,500).GetCoordinate(0),510); a.FlippedCoordinates=true; TestSuite.Near(new CoordinateCalculator(a,10,500).GetCoordinate(0),10); });
        suite.Run("log coordinate inverse",()=> { var a=new LogarithmicNumericAxis {VisibleRange=new(.001,1e6)}; var c=new CoordinateCalculator(a,0,900); for(int e=-3;e<=6;e++) { double v=Math.Pow(10,e); TestSuite.Near(c.GetCoordinate(v),(e+3)*100); TestSuite.Near(c.GetDataValue(c.GetCoordinate(v)),v); } TestSuite.True(double.IsNaN(c.GetCoordinate(-1))); });
        suite.Run("log range rejects zero",()=> { var a=new LogarithmicNumericAxis(); TestSuite.Throws<ArgumentOutOfRangeException>(()=>a.VisibleRange=new(0,10)); TestSuite.Throws<ArgumentOutOfRangeException>(()=>a.LogarithmicBase=1); });
        suite.Run("date formatting UTC",()=> { var a=new DateTimeAxis {TextFormatting="yyyy-MM-dd HH:mm"}; TestSuite.Equal(a.Format(0),"1970-01-01 00:00"); });
        suite.Run("category labels",()=> { var a=new CategoryDateTimeAxis {Labels=new[]{"A","B","C"}}; TestSuite.Equal(a.Format(1),"B"); });
        suite.Run("numeric tick boundaries",()=> { var a=new NumericAxis {VisibleRange=new(-.31,.79)}; var ticks=TickGenerator.Generate(a,800); TestSuite.True(ticks.Any(t=>t.IsMajor)); TestSuite.True(ticks.All(t=>t.Value>=a.VisibleRange.Min-1e-12&&t.Value<=a.VisibleRange.Max+1e-12)); TestSuite.True(ticks.Count<300); });
        suite.Run("log tick powers",()=> { var a=new LogarithmicNumericAxis {VisibleRange=new(1,1000)}; var ticks=TickGenerator.Generate(a,1000); foreach(double v in new[]{1.0,10,100,1000}) TestSuite.True(ticks.Any(t=>t.IsMajor&&Math.Abs(t.Value-v)<1e-9)); });
        suite.Run("calendar ticks align months",()=> { var a=new DateTimeAxis {VisibleRange=new(new DateTimeOffset(2024,1,15,0,0,0,TimeSpan.Zero).ToUnixTimeMilliseconds(),new DateTimeOffset(2025,1,15,0,0,0,TimeSpan.Zero).ToUnixTimeMilliseconds())}; var ticks=TickGenerator.Generate(a,600); TestSuite.True(ticks.Count>2); TestSuite.True(ticks.All(t=>DateTimeOffset.FromUnixTimeMilliseconds((long)t.Value).Day==1)); });
        suite.Run("color map interpolation and gaps",()=> { var map=new ColorMap(new(0,new(0,0,0)),new(1,new(200,100,50))); TestSuite.Equal(map.Sample(.5),new ColorRgba(100,50,25)); TestSuite.Equal(map.Sample(double.NaN),ColorRgba.Transparent); });
        suite.Run("color map invalid stops",()=> { TestSuite.Throws<ArgumentException>(()=>new ColorMap(new(.1,ColorRgba.Black),new(1,ColorRgba.White))); TestSuite.Throws<ArgumentException>(()=>new ColorMap(new(0,ColorRgba.Black),new(0,ColorRgba.White),new(1,ColorRgba.White))); });
        suite.Run("series channel validation",()=> { var s=new FastCandlestickRenderableSeries(); TestSuite.Throws<ArgumentException>(()=>s.DataSeries=new XyDataSeries()); s.DataSeries=new OhlcDataSeries(); });
        suite.Run("model default validation",()=> { using var model=new ChartModel(); TestSuite.Equal(model.Validate().Count,0); model.RenderableSeries.Add(new RenderableSeries{XAxisId="missing"}); TestSuite.Equal(model.Validate().Count,1); });
        suite.Run("duplicate axis IDs diagnosed",()=> { using var model=new ChartModel(); model.XAxes.Add(new NumericAxis{Id="X"}); TestSuite.True(model.Validate().Any(e=>e.Contains("unique"))); });
        suite.Run("series mutation invalidates model",()=> { using var model=new ChartModel(); var d=new XyDataSeries(); var s=new RenderableSeries{DataSeries=d}; model.RenderableSeries.Add(s); long revision=model.Revision; d.Append(1,2); TestSuite.True(model.Revision>revision); revision=model.Revision; s.Stroke=ColorRgba.White; TestSuite.True(model.Revision>revision); });
        suite.Run("removed series unsubscribed",()=> { using var model=new ChartModel(); var d=new XyDataSeries(); var s=new RenderableSeries{DataSeries=d}; model.RenderableSeries.Add(s); model.RenderableSeries.Clear(); long revision=model.Revision; d.Append(1,2); TestSuite.Equal(model.Revision,revision); s.Dispose(); });
        suite.Run("zoom extents contains data",()=> { using var model=new ChartModel(); var d=new XyDataSeries(); d.AppendRange([10,20],[-5,10]); model.RenderableSeries.Add(new RenderableSeries{DataSeries=d}); model.ZoomExtents(); TestSuite.True(model.XAxis.VisibleRange.Contains(10)&&model.XAxis.VisibleRange.Contains(20)); TestSuite.True(model.YAxis.VisibleRange.Contains(-5)&&model.YAxis.VisibleRange.Contains(10)); });
        suite.Run("hidden series excluded from extents",()=> { using var model=new ChartModel(); var d=new XyDataSeries(); d.AppendRange([0,1],[0,1]); var other=new XyDataSeries(); other.AppendRange([0,1],[100,200]); model.RenderableSeries.Add(new RenderableSeries{DataSeries=d}); model.RenderableSeries.Add(new RenderableSeries{DataSeries=other,IsVisible=false}); model.ZoomExtents(); TestSuite.True(model.YAxis.VisibleRange.Max<2); });
        suite.Run("OHLC range uses low high",()=> { using var model=new ChartModel(); var d=new OhlcDataSeries(); d.Append(0,10,20,-5,12); model.RenderableSeries.Add(new FastCandlestickRenderableSeries{DataSeries=d}); model.ZoomExtents(); TestSuite.True(model.YAxis.VisibleRange.Contains(-5)&&model.YAxis.VisibleRange.Contains(20)); });
        suite.Run("signed stacking",()=> { using var model=new ChartModel(); var a=new XyDataSeries(); a.AppendRange([0,1],[3,-2]); var b=new XyDataSeries(); b.AppendRange([0,1],[5,-7]); var sa=new StackedColumnRenderableSeries{DataSeries=a}; var sb=new StackedColumnRenderableSeries{DataSeries=b}; model.RenderableSeries.Add(sa); model.RenderableSeries.Add(sb); var stacks=StackCalculator.Calculate(model); TestSuite.Near(stacks[sb].Lower[0],3); TestSuite.Near(stacks[sb].Upper[0],8); TestSuite.Near(stacks[sb].Upper[1],-9); model.ZoomExtents(); TestSuite.True(model.YAxis.VisibleRange.Contains(-9)&&model.YAxis.VisibleRange.Contains(8)); });
        suite.Run("percent stacking",()=> { using var model=new ChartModel(); for(int i=0;i<2;i++) { var d=new XyDataSeries(); d.Append(0,i==0?1:3); model.RenderableSeries.Add(new StackedColumnRenderableSeries{DataSeries=d,StackMode=StackMode.Percent}); } var stacks=StackCalculator.Calculate(model); TestSuite.Near(stacks[model.RenderableSeries[0]].Upper[0],25); TestSuite.Near(stacks[model.RenderableSeries[1]].Upper[0],100); });
        suite.Run("stack by X rather than array index",()=> { using var model=new ChartModel(); var a=new XyDataSeries(); a.AppendRange([0,1],[2,3]); var b=new XyDataSeries(); b.AppendRange([1,2],[4,5]); model.RenderableSeries.Add(new StackedColumnRenderableSeries{DataSeries=a}); var s=new StackedColumnRenderableSeries{DataSeries=b}; model.RenderableSeries.Add(s); var stack=StackCalculator.Calculate(model)[s]; TestSuite.Near(stack.Lower[0],3); TestSuite.Near(stack.Lower[1],0); });
        suite.Run("aspect ratio fit does not crop",()=> { using var model=new ChartModel{AspectRatio=1}; model.XAxis.VisibleRange=new(0,10); model.YAxis.VisibleRange=new(0,10); model.ApplyAspectRatio(1000,500); TestSuite.Near(model.XAxis.VisibleRange.Size,20); TestSuite.Near(model.YAxis.VisibleRange.Size,10); });
        suite.Run("annotations invalidate",()=> { using var model=new ChartModel(); var a=new BoxAnnotation(); model.Annotations.Add(a); long r=model.Revision; a.X1=5; TestSuite.True(model.Revision>r); });
    }
}
